fn largest_squared_value() -> i32 {
    // Step 1: Identify odd and even numbers between 94 and 126.
    let mut odd_and_even_numbers: Vec<i32> = (94..=126)
        .iter()
        .filter_map(|&x| {
            if x % 2 == 0 { None } else { Some(*x) }
        })
        .collect(); // Remove even numbers first since they are irrelevant here

    // Step 2: Filter out the remaining numbers that are divisible by 7.
    odd_and_even_numbers.retain(|&x| x % 7 == 0);

    // Step 3: Square each remaining number.
    let squared_numbers = odd_and_even_numbers.iter().map(|&x| x * x).collect::<Vec<_>>();

    // Step 4: Find the largest squared number.
    // Since we already filtered out non-divisible-by-7 numbers,
    // the largest number must be included;
    // otherwise, panic would occur during indexing operation.
    assert!(squared_numbers.into_iter().max().is_some());
    let max_squared: Option<i32> = squared_numbers.into_iter().max();

    // Step 5: Return the largest squered number.
    *max_squared.unwrap_or(&0)
}

